UNTRANSLATED_NAME_PATTERNS = (
    r"\b(?:sveti|sveta|bogorod|gospod|vaznes|rozhdest|uspen|vaveden|"
    r"pokrov|prorok|arhangel|mchen|prepod|troitsa|iztochnik|hram|manastir|"
    r"paraklis|velikom|ravnoapost|bezsreb|predtecha|krastitel|stolpnik|"
    r"yoan|nikolay|dimitur|georgi|petka|nedelya)\w*\b",
)

CLERGY_PATTERNS = (
    r"\b(?:протойерей|свещеник|свещ\.|иконом|архимандрит|игумен|"
    r"иеромонах|монахиня|ефимерий|тел\.|телефон|gsm)\b",
)


def clean(source):
    out = {key: value for key, value in source.items()
           if value not in (None, "", [])}
    out.setdefault("checked", CHECKED)
    sources = list(out.get("sources") or [])
    if not sources or len(sources) > 3:
        raise ValueError("%s must cite one to three sources" % out.get("id"))
    for url in sources:
        parsed = urlparse(url)
        if parsed.scheme != "https" or not parsed.netloc or url not in SOURCE_URLS:
            raise ValueError("%s carries an unapproved source: %s" %
                             (out.get("id"), url))
    out["sources"] = sources
    out["cite"] = list(sources)
    return out


def validate_rows(source_rows, branch_parent, all_seen):
    rows = []
    branch_seen = {branch_parent}
    countries = set()
    for source in source_rows:
        item = clean(source)
        row_id = item.get("id")
        if not row_id or row_id in all_seen:
            raise ValueError("duplicate or missing id: %s" % row_id)
        if item.get("parent") not in branch_seen:
            raise ValueError("%s hangs off an unknown parent: %s" %
                             (row_id, item.get("parent")))
        if item.get("kind") not in {"diocese", "parish", "monastery"}:
            raise ValueError("%s has unsupported kind" % row_id)
        if item.get("rank") not in {
                "Deanery", "Cathedral", "Church", "Chapel", "Monastery",
                "Convent", "Metochion"}:
            raise ValueError("%s has unsupported rank" % row_id)
        if item["rank"] == "Deanery":
            if item["kind"] != "diocese" or item["parent"] != branch_parent:
                raise ValueError("%s has malformed deanery hierarchy" % row_id)
        elif item["kind"] == "diocese":
            raise ValueError("%s uses diocese kind for a body" % row_id)
        if item.get("country") != "BG":
            raise ValueError("%s has invalid country" % row_id)
        if not item.get("local") or not item.get("name") or not item.get("seat"):
            raise ValueError("%s has no usable local, English name, or seat" % row_id)
        english = item["name"]
        if any("\u0400" <= char <= "\u04ff" for char in english):
            raise ValueError("%s has Cyrillic in its English name" % row_id)
        if item["rank"] != "Deanery":
            designation = re.split(
                r"\s+(?:Cathedral|Church|Chapel|Monastery|Convent|Metochion)\s+in\s+",
                english, maxsplit=1,
            )[0]
            if any(re.search(pattern, designation, flags=re.I)
                   for pattern in UNTRANSLATED_NAME_PATTERNS):
                raise ValueError("%s has untranslated ecclesiastical text" % row_id)
            seat_en = ENGLISH_SEATS.get(item["seat"])
            if not seat_en or not english.endswith(" in " + seat_en):
                raise ValueError("%s has an unguarded English seat" % row_id)
        if any(re.search(pattern, item["local"], flags=re.I)
               for pattern in CLERGY_PATTERNS):
            raise ValueError("%s leaks clergy or contact data" % row_id)
        rendered = json.dumps(item, ensure_ascii=False)
        if any(mark in rendered for mark in (
                "\u2013", "\u2014", "\ufffd", "\u201e", "\u201c", "\u201d")):
            raise ValueError("%s has forbidden punctuation or encoding" % row_id)
        if "  " in english or re.search(r"\s[-,:;]\s*$", english):
            raise ValueError("%s has malformed English punctuation" % row_id)
        all_seen.add(row_id)
        branch_seen.add(row_id)
        countries.add(item["country"])
        rows.append(item)
    return rows, countries


def validate_duplicate_guards(payloads, direct_russia, direct_romania):
    groups = defaultdict(list)
    all_rows = [row for payload in payloads.values() for row in payload["rows"]]
    all_rows.extend(direct_russia)
    all_rows.extend(direct_romania)
    for row in all_rows:
        if row["rank"] == "Deanery":
            continue
        key = "|".join((row["parent"], row["rank"], row["name"]))
        groups[key].append(row["id"])
    actual = {key: sorted(ids) for key, ids in groups.items() if len(ids) > 1}
    if actual != ALLOWED_DISTINCT_SAME_NAME:
        raise ValueError("same-name physical duplicate guard changed")
    by_id = {row["id"]: row for row in all_rows}
    if set(by_id).intersection(PROVEN_DEDUPE_SURVIVORS) != PROVEN_DEDUPE_SURVIVORS:
        raise ValueError("a proven physical-dedupe survivor is missing")
    if any(by_id[row_id]["rank"] != "Monastery"
           for row_id in PROVEN_DEDUPE_SURVIVORS):
        raise ValueError("a proven physical-dedupe survivor changed rank")


def validate_ledger():
    path = Path(__file__).with_name("directory_candidates") / "bulgaria.json"
    ledger = json.loads(path.read_text(encoding="utf-8"))
    if ledger.get("checked") != CHECKED:
        raise ValueError("candidate ledger check date changed")
    if ledger.get("published_summary") != PUBLISHED_SUMMARY_EXPECTED:
        raise ValueError("candidate ledger publication summary changed")
    holds = {item["id"]: item for item in ledger.get("holds", [])}
    counts = {key: value.get("count") for key, value in holds.items()}
    if counts != LEDGER_EXPECTED:
        raise ValueError("candidate hold counts changed: %r" % counts)
    for item in holds.values():
        if "records" in item and len(item["records"]) != item["count"]:
            raise ValueError("candidate hold record count changed: %s" % item["id"])
    dedupes = {item["id"]: item for item in ledger.get("deduplications", [])}
    dedupe_counts = {key: value.get("count") for key, value in dedupes.items()}
    if dedupe_counts != DEDUPE_LEDGER_EXPECTED:
        raise ValueError("candidate dedupe counts changed: %r" % dedupe_counts)
    for item in dedupes.values():
        if len(item.get("records", [])) != item["count"]:
            raise ValueError("candidate dedupe record count changed: %s" % item["id"])
    uncertainties = {item["id"]: item for item in ledger.get("uncertainties", [])}
    uncertainty_counts = {
        key: value.get("count") for key, value in uncertainties.items()
    }
    if uncertainty_counts != UNCERTAINTY_LEDGER_EXPECTED:
        raise ValueError("candidate uncertainty counts changed: %r" %
                         uncertainty_counts)
    for item in uncertainties.values():
        if len(item.get("records", [])) != item["count"]:
            raise ValueError("candidate uncertainty record count changed: %s" %
                             item["id"])
    rendered = json.dumps(ledger, ensure_ascii=False)
    if any(mark in rendered for mark in (
            "\u2013", "\u2014", "\ufffd", "\u201e", "\u201c", "\u201d")):
        raise ValueError("candidate ledger has forbidden punctuation")


def build_all():
    payloads = {}
    all_seen = set(ROWS)
    all_seen.update({"russia", "romania"})
    for parent, source_rows in ROWS.items():
        rows, countries = validate_rows(source_rows, parent, all_seen)
        payload = {"v": 1, "parent": parent, "rows": rows}
        if len(countries) == 1:
            payload["country"] = next(iter(countries))
        payloads[parent] = payload
    direct_russia, _ = validate_rows(DIRECT_RUSSIA_ROWS, "russia", all_seen)
    direct_romania, _ = validate_rows(DIRECT_ROMANIA_ROWS, "romania", all_seen)
    counts = {parent: len(payload["rows"])
              for parent, payload in payloads.items()}
    if counts != EXPECTED:
        raise ValueError("Bulgaria branch counts changed: %r" % counts)
    body_counts = {
        parent: sum(row["rank"] != "Deanery" for row in payload["rows"])
        for parent, payload in payloads.items()
    }
    deanery_counts = {
        parent: sum(row["rank"] == "Deanery" for row in payload["rows"])
        for parent, payload in payloads.items()
    }
    if body_counts != EXPECTED_BODY_COUNTS:
        raise ValueError("Bulgaria body counts changed: %r" % body_counts)
    if deanery_counts != EXPECTED_DEANERY_COUNTS:
        raise ValueError("Bulgaria deanery counts changed: %r" % deanery_counts)
    all_rows = [row for payload in payloads.values() for row in payload["rows"]]
    all_rows.extend(direct_russia)
    all_rows.extend(direct_romania)
    parent_counts = Counter(row["parent"] for row in all_rows
                            if row["rank"] != "Deanery"
                            and row["parent"].startswith("bg-"))
    if dict(sorted(parent_counts.items())) != EXPECTED_PARENT_BODY_COUNTS:
        raise ValueError("deanery body counts changed: %r" % parent_counts)
    rank_counts = Counter(row["rank"] for row in all_rows)
    if dict(sorted(rank_counts.items())) != EXPECTED_RANK_COUNTS:
        raise ValueError("rank counts changed: %r" % rank_counts)
    source_counts = Counter(url for row in all_rows for url in row["sources"])
    if dict(sorted(source_counts.items())) != EXPECTED_SOURCE_OCCURRENCES:
        raise ValueError("source occurrence counts changed")
    if len(direct_russia) != DIRECT_RUSSIA_EXPECTED:
        raise ValueError("Russian direct count changed: %d" % len(direct_russia))
    if len(direct_romania) != DIRECT_ROMANIA_EXPECTED:
        raise ValueError("Romanian direct count changed: %d" % len(direct_romania))
    if sum(counts.values()) != TOTAL_BULGARIA_EXPECTED:
        raise ValueError("total Bulgaria count changed")
    validate_duplicate_guards(payloads, direct_russia, direct_romania)
    validate_ledger()
    return payloads, direct_russia, direct_romania


def build():
    return build_all()[0]


def main():
    parser = argparse.ArgumentParser()
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--dump", action="store_true")
    args = parser.parse_args()
    try:
        payloads, direct_russia, direct_romania = build_all()
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print("directory Bulgaria: %s" % exc, file=sys.stderr)
        return 1
    if args.dump:
        print(json.dumps({
            "branches": payloads,
            "direct_russia_rows": direct_russia,
            "direct_romania_rows": direct_romania,
        }, ensure_ascii=False, indent=2, sort_keys=True))
    total = sum(len(payload["rows"]) for payload in payloads.values())
    print("Bulgaria: %d verified rows across %d canonical parents, plus %d Russian and %d Romanian direct rows" %
          (total, len(payloads), len(direct_russia), len(direct_romania)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
